// Original Japanese passages and German teaching material. Correct choice is authored first;
// the packager places it without changing any legacy question. Ruby is authored, never inferred.
const q = (prompt, evidence, ...choices) => [prompt, evidence, ...choices.map(c => c.split(' ~ '))];
const u = (format, title, texts, translation, glossary, note, questions) =>
  [format, 'reading', title, note, Array.isArray(texts) ? texts : [texts], translation, glossary, note, questions];
